(()=>{if(!document.body.classList.contains('ebook-detail')||!matchMedia('(pointer:fine)').matches)return;const key='jh_ebook_exit_prompt_v2',days=14*864e5;try{const t=Number(localStorage.getItem(key)||0);if(t&&Date.now()-t<days)return}catch{}const d=document.createElement('dialog');d.className='newsletter-exit-dialog';d.setAttribute('aria-labelledby','newsletter-exit-title');d.innerHTML=`<form method="dialog" class="newsletter-exit-dialog__close"><button type="submit" aria-label="Close AI Edge prompt">×</button></form><div data-newsletter-shell data-newsletter-source="ebook-exit"><h2 id="newsletter-exit-title">Want the useful bits before you go?</h2><p>AI Edge keeps the practical AI signal together, with the free plain-English glossary.</p><a class="button" data-newsletter-cta data-placement="ebook-exit" href="/newsletter/?source=ebook-exit&placement=exit">Join AI Edge</a></div>`;document.body.appendChild(d);let shown=false;const mark=()=>{try{localStorage.setItem(key,String(Date.now()))}catch{}};const show=e=>{if(shown||e.clientY>8||!d.showModal)return;shown=true;mark();d.showModal();document.removeEventListener('mouseout',show)};d.addEventListener('close',mark);document.addEventListener('mouseout',show)})();
